#!/usr/bin/env bash
set -e

echo "=========================================================="
echo "🚀 Setting up Kurdistan Digital Government AI Droplet..."
echo "=========================================================="

# 1. 2GB Swap Memory for optimal 1GB Droplet stability
if [ ! -f /swapfile ]; then
    echo "Creating 2GB swap memory..."
    fallocate -l 2G /swapfile || dd if=/dev/zero of=/swapfile bs=1M count=2048
    chmod 600 /swapfile
    mkswap /swapfile
    swapon /swapfile
    echo '/swapfile none swap sw 0 0' >> /etc/fstab
    echo "✅ Swap memory enabled."
fi

# 2. Update and install packages
echo "Installing Python & Nginx..."
export DEBIAN_FRONTEND=noninteractive
apt-get update -y
apt-get install -y python3 python3-pip python3-venv nginx curl ufw

# 3. Create app directory and extract backend files
echo "Extracting backend application..."
mkdir -p /var/www/goverment-ai/backend
cat << 'PAYLOAD_EOF' | base64 -d | tar -xz -C /var/www/goverment-ai/backend

PAYLOAD_EOF
echo "✅ Backend files extracted."

# 4. Write .env configuration
cat << 'EOF' > /var/www/goverment-ai/backend/.env
OPENAI_API_KEY=${OPENAI_API_KEY:-"YOUR_OPENAI_API_KEY"}
OPENAI_MODEL=gpt-4o-mini
GROQ_API_KEY=${GROQ_API_KEY:-""}
GROQ_MODEL=qwen/qwen3.8-27b
SIMILARITY_THRESHOLD=0.28
JWT_SECRET_KEY=${JWT_SECRET_KEY:-"$(openssl rand -hex 32 2>/dev/null || echo 'change-this-secret-key-in-production')"}
JWT_ALGORITHM=HS256
ACCESS_TOKEN_EXPIRE_MINUTES=1440
DATABASE_URL=${DATABASE_URL:-"YOUR_NEON_DATABASE_URL"}
ALLOWED_ORIGINS=*
EOF

# 5. Setup Python virtual environment
echo "Setting up Python virtualenv and dependencies (takes ~1 min)..."
cd /var/www/goverment-ai/backend
python3 -m venv venv
./venv/bin/pip install --upgrade pip
./venv/bin/pip install -r requirements.txt
echo "✅ Dependencies installed."

# 6. Configure systemd service
cat << 'EOF' > /etc/systemd/system/goverment-ai.service
[Unit]
Description=Kurdistan Government AI Backend Service
After=network.target

[Service]
User=root
WorkingDirectory=/var/www/goverment-ai/backend
ExecStart=/var/www/goverment-ai/backend/venv/bin/uvicorn main:app --host 127.0.0.1 --port 8000 --workers 2
Restart=always
RestartSec=3
EnvironmentFile=/var/www/goverment-ai/backend/.env

[Install]
WantedBy=multi-user.target
EOF

# 7. Configure Nginx Reverse Proxy
cat << 'EOF' > /etc/nginx/sites-available/default
server {
    listen 80 default_server;
    listen [::]:80 default_server;

    server_name _;

    client_max_body_size 20M;

    location / {
        proxy_pass http://127.0.0.1:8000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
EOF

# 8. Start and enable service & Nginx
systemctl daemon-reload
systemctl enable goverment-ai
systemctl restart goverment-ai
systemctl restart nginx

# 9. Firewall
ufw allow 80/tcp || true
ufw allow 22/tcp || true

echo "=========================================================="
echo "🎉 DEPLOYMENT COMPLETE!"
echo "Server is live on http://164.92.207.159:80"
echo "Testing health:"
sleep 2
curl -s http://127.0.0.1/ | head -n 5
echo ""
echo "=========================================================="